package com.example.reviewreminder;

import android.app.AlertDialog;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.UUID;

public final class ReviewActivity extends ScreenActivity {
    private WordUi ui;private long id,seed;private int expectedStage,mode,forceMode=-1,lastAutoSpoken=-1;private JSONArray words;private ReviewSession session;private boolean revealed,completed,changing,practice;private String selectionId;private SpeechManager speech;private final Feedback interaction=new Feedback();private StringBuilder answers=new StringBuilder();private LinearLayout feedback;private View cardView;private java.util.concurrent.Future<?> pendingAi;

    @Override public void onCreate(Bundle state){super.onCreate(state);interaction.prepare(this);ui=new WordUi(this);speech=new SpeechManager(this);id=getIntent().getLongExtra("taskId",0);selectionId=getIntent().getStringExtra("selectionId");practice=getIntent().getBooleanExtra("practice",false)||selectionId!=null||(state!=null&&state.getBoolean("practice"));forceMode=getIntent().hasExtra("forceMode")?getIntent().getIntExtra("forceMode",-1):(state==null?-1:state.getInt("forceMode",-1));
        try{if(selectionId!=null){JSONObject selection=TrainingStore.selection(this,selectionId);if(selection==null)throw new Exception("训练选词已失效");words=selection.getJSONArray("words");}else{JSONObject task=Store.find(Store.tasks(this),id);if(task==null)throw new Exception("任务不存在");words=task.getJSONArray("words");}if(words.length()==0)throw new Exception("词组为空");expectedStage=state==null?taskStage():state.getInt("stage");mode=Store.prefs(this).getInt("reviewMode",0);seed=state==null?System.nanoTime():state.getLong("seed");session=new ReviewSession(words.length(),selectionId==null&&Store.prefs(this).getBoolean("shuffleWords",false),seed);String previous=state==null?"":state.getString("answers","");for(char answer:previous.toCharArray())if(!session.ended()){session.answer(answer=='1');answers.append(answer);}if(state!=null){revealed=state.getBoolean("revealed");lastAutoSpoken=state.getInt("lastAutoSpoken",-1);}show();}catch(Exception e){ui.toast(e.getMessage());finish();}}
    private int taskStage(){if(selectionId!=null)return 0;JSONObject task=Store.find(Store.tasks(this),id);return task==null?0:task.optInt("stage");}
    @Override protected void onSaveInstanceState(Bundle out){out.putLong("seed",seed);out.putInt("stage",expectedStage);out.putInt("forceMode",forceMode);out.putInt("lastAutoSpoken",lastAutoSpoken);out.putString("answers",answers.toString());out.putBoolean("revealed",revealed);out.putBoolean("practice",practice);super.onSaveInstanceState(out);}
    private boolean chineseFirst(JSONObject word){if(forceMode==0)return false;if(forceMode==1)return !word.optString("chinese").isEmpty();return !word.optString("chinese").isEmpty()&&(mode==1||(mode==2&&((seed+session.current()*31)&1)==0));}
    private boolean sessionChineseBiased(){return forceMode==1||(forceMode<0&&mode==1);}
    private void speak(String value,boolean automatic){if(automatic&&lastAutoSpoken==session.answered())return;speakWordThenExample(value,null,automatic);}
    private void speakWordThenExample(String english,String example,boolean automatic){if(automatic&&!Store.prefs(this).getBoolean("autoSpeak",true))return;if(english==null||english.trim().isEmpty())return;if(automatic)lastAutoSpoken=session.answered();String extra=example==null?"":example.trim();speech.speak(english.trim()+(extra.isEmpty()?"":". "+extra),"review");}

    private void show(){
        if(session.ended()){summary();return;}ui.start(practice?"任意复习":"快速复习");LinearLayout progressHeader=ui.row();TextView position=ui.text((session.answered()+1)+" / "+session.total()+" 张"+(practice?" · 不计计划轮次":""),14,WordUi.INK);position.setTypeface(null,android.graphics.Typeface.BOLD);progressHeader.addView(position,new LinearLayout.LayoutParams(0,-2,1));progressHeader.addView(ui.chip("第 "+(session.answered()+1)+" 张",WordUi.GREEN,WordUi.SOFT));ui.body.addView(progressHeader);ui.gap(ui.body,10);ui.body.addView(ui.progress(session.answered()*100/session.total()),new LinearLayout.LayoutParams(-1,ui.dp(5)));ui.gap(ui.body,20);JSONObject word=words.optJSONObject(session.current());boolean zh=chineseFirst(word);
        LinearLayout card=ui.card();card.setMinimumHeight(ui.dp(292));card.setPadding(ui.dp(24),ui.dp(24),ui.dp(24),ui.dp(24));TextView label=ui.text(zh?"中文释义":"英文单词",13,WordUi.MUTED);card.addView(label);ui.gap(card,28);TextView front=ui.text(zh?word.optString("chinese"):word.optString("english"),zh?27:36,WordUi.INK);front.setTypeface(null,android.graphics.Typeface.BOLD);front.setMaxLines(3);card.addView(front);ui.gap(card,24);
        TextView back=ui.text(zh?word.optString("english"):word.optString("chinese",""),22,WordUi.GREEN);back.setPadding(ui.dp(16),ui.dp(14),ui.dp(16),ui.dp(14));back.setBackground(Theme.shape(this,Theme.PRIMARY_SOFT,Theme.RADIUS_CHIP));back.setVisibility(revealed?View.VISIBLE:View.INVISIBLE);card.addView(back,new LinearLayout.LayoutParams(-1,-2));
        String example=word.optString("example");TextView sentence=ui.text(example,16,WordUi.MUTED);sentence.setLineSpacing(0,1.2f);sentence.setPadding(0,ui.dp(18),0,0);sentence.setVisibility(example.isEmpty()?View.GONE:revealed?View.VISIBLE:View.INVISIBLE);sentence.setContentDescription("朗读例句："+example);sentence.setOnClickListener(v->speech.speak(example,"example"));Motion.press(sentence);card.addView(sentence);
        TextView mastery=ui.text(Mastery.label(Mastery.level(word)),13,WordUi.MUTED);mastery.setPadding(0,ui.dp(14),0,0);mastery.setVisibility(revealed?View.VISIBLE:View.INVISIBLE);card.addView(mastery);ui.body.addView(card);cardView=card;
        if(ConnectionImages.exists(this,word.optString("connectionImage"))){ui.gap(ui.body,12);Button connection=ui.ghostButton("查看连接图",v->openConnection(word));UiIcons.apply(connection,Theme.PRIMARY);ui.body.addView(connection);}
        ui.gap(ui.body,20);
        FrameLayout actionSlot=new FrameLayout(this);actionSlot.setMinimumHeight(ui.dp(56));feedback=ui.col();actionSlot.addView(feedback,new FrameLayout.LayoutParams(-1,-2));Button pronounce=ui.ghostButton("朗读单词",v->speak(word.optString("english"),false));UiIcons.apply(pronounce,Theme.PRIMARY);pronounce.setVisibility(!zh||revealed?View.VISIBLE:View.GONE);Button reveal=ui.button("显示答案",true,v->revealAnswer(v,word,back,sentence,example,pronounce));reveal.setVisibility(revealed?View.GONE:View.VISIBLE);actionSlot.addView(reveal,new FrameLayout.LayoutParams(-1,-2));ui.body.addView(actionSlot);if(revealed)showFeedback();ui.gap(ui.body,10);ui.body.addView(pronounce);ui.gap(ui.body,4);
        ui.body.addView(ui.textButton("编辑这张卡",v->{if(!changing)edit(word);}));Motion.enter(card,1);if(revealed)speakWordThenExample(word.optString("english"),example,true);else if(!zh)speak(word.optString("english"),true);
    }
    private void revealAnswer(View button,JSONObject word,TextView back,TextView sentence,String example,Button pronounce){if(revealed||changing)return;interaction.reveal(button);revealed=true;back.setVisibility(View.VISIBLE);Motion.enter(back);if(!example.isEmpty()){sentence.setVisibility(View.VISIBLE);Motion.enter(sentence);}button.setVisibility(View.GONE);pronounce.setVisibility(View.VISIBLE);lastAutoSpoken=-1;speakWordThenExample(word.optString("english"),example,true);showFeedback();}
    private void showFeedback(){final int position=session.answered();LinearLayout buttons=ui.row();LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-2,1);left.rightMargin=ui.dp(8);buttons.addView(ui.dangerSoftButton("忘记了",v->answer(false,position,v)),left);buttons.addView(ui.button("记得",true,v->answer(true,position,v)),new LinearLayout.LayoutParams(0,-2,1));feedback.removeAllViews();feedback.addView(buttons);Motion.enter(buttons);}
    private void answer(boolean known,int expected,View source){if(changing||!revealed||session.ended()||session.answered()!=expected)return;boolean firstAttempt=session.attemptsForCurrent()==0;JSONObject word=words.optJSONObject(session.current());long sourceTask=word.optLong("_taskId",id);int sourceIndex=word.optInt("_wordIndex",session.current());String wordId=Words.stableId(word);int reviewRound=practice?0:expectedStage+1;try{if(!known)WrongBook.record(this,sourceTask,sourceIndex,reviewRound,selectionId==null?words:null,"review:"+seed+":"+expected+":"+sourceIndex,wordId);if(!practice)Mastery.applyAnswer(this,sourceTask,sourceIndex,known,firstAttempt,selectionId==null?words:null,wordId);}catch(Exception e){ui.toast("结果保存失败，尚未提交本题："+e.getMessage());return;}interaction.respond(source,known?Feedback.KNOWN:Feedback.RETRY);changing=true;speech.stop();session.answer(known);answers.append(known?'1':'0');revealed=false;Motion.leave(cardView,known?1:-1,()->{if(isFinishing()||isDestroyed())return;changing=false;show();});}

    private void openConnection(JSONObject word){if(!ConnectionImages.exists(this,word.optString("connectionImage"))){ui.toast("连接图已丢失");return;}Motion.open(this,new android.content.Intent(this,ConnectionImageActivity.class).putExtra("path",word.optString("connectionImage")).putExtra("english",word.optString("english")));}
    private void edit(JSONObject word){LinearLayout form=ui.col();form.setPadding(ui.dp(20),0,ui.dp(20),0);EditText en=new EditText(this),zh=new EditText(this),ex=new EditText(this);en.setText(word.optString("english"));zh.setText(word.optString("chinese"));ex.setText(word.optString("example"));en.setHint("英文");zh.setHint("中文");ex.setHint("例句（可留空）");form.addView(en);form.addView(zh);form.addView(ex);AlertDialog d=new AlertDialog.Builder(this).setTitle("编辑单词卡").setView(form).setNegativeButton("取消",null).setPositiveButton("保存",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(en.getText().toString().trim().isEmpty()){en.setError("英文不能为空");return;}try{long targetId=word.optLong("_taskId",id);int targetIndex=word.optInt("_wordIndex",session.current());JSONArray all=Store.tasks(this);JSONObject current=Store.find(all,targetId);if(current==null)throw new Exception("任务不存在");JSONArray stored=current.getJSONArray("words");JSONObject target=stored.getJSONObject(targetIndex);Words.stableId(target);target.put("english",en.getText().toString().trim()).put("chinese",zh.getText().toString().trim()).put("example",ex.getText().toString().trim());Words.stableId(target);Store.save(this,all);word.put("english",target.optString("english")).put("chinese",target.optString("chinese")).put("example",target.optString("example")).put("wordId",Words.stableId(target));d.dismiss();show();}catch(Exception e){ui.toast(e.getMessage());}}));d.show();}

    private void summary(){ui.start(practice?"练习结束":"本轮已看完");ui.body.addView(ui.text("共 "+words.length()+" 个单词，标记“忘记了” "+session.repeats()+" 次",18,WordUi.INK));ui.gap(ui.body,8);if(practice)ui.body.addView(ui.text("任意复习不计入计划轮次，也不会推进提醒。",14,WordUi.MUTED));else ui.body.addView(ui.text("平均掌握度 "+String.format(java.util.Locale.CHINA,"%.1f",Mastery.average(words))+"/5",14,WordUi.MUTED));ui.gap(ui.body,18);JSONObject task=Store.find(Store.tasks(this),id);boolean eligible=!practice&&task!=null&&!task.optBoolean("done")&&task.optInt("stage")==expectedStage;if(eligible){ui.body.addView(ui.button("完成本轮并选择拼写",true,v->chooseSpelling()));ui.gap(ui.body,12);}ui.body.addView(ui.button(practice?"再练一遍":"再复习一遍",practice,v->{seed=System.nanoTime();session=new ReviewSession(words.length(),selectionId==null&&Store.prefs(this).getBoolean("shuffleWords",false),seed);lastAutoSpoken=-1;answers.setLength(0);revealed=false;show();}));ui.gap(ui.body,10);ui.body.addView(ui.ghostButton("更多选项",v->summaryMore()));ui.gap(ui.body,10);ui.body.addView(ui.secondaryButton("返回主页",v->finish()));Motion.enter(ui.body);}
    private void summaryMore(){java.util.ArrayList<String> labels=new java.util.ArrayList<>();int flipTo=sessionChineseBiased()?0:1;labels.add(flipTo==1?"换向再复习（先中文）":"换向再复习（先英文）");if(session.repeats()>0&&selectionId==null)labels.add("错词义项练习");if(!practice)labels.add("AI 本轮复盘");new AlertDialog.Builder(this).setTitle("更多选项").setItems(labels.toArray(new String[0]),(d,which)->{String label=labels.get(which);if(label.startsWith("换向")){IntentBuilder();}else if(label.startsWith("错词")){Motion.open(this,new android.content.Intent(this,SenseQuizActivity.class).putExtra("taskId",id).putExtra("wrongOnly",true));finish();}else aiSummary();}).setNegativeButton("取消",null).show();}
    private void IntentBuilder(){android.content.Intent intent=new android.content.Intent(this,ReviewActivity.class).putExtra("taskId",id).putExtra("forceMode",sessionChineseBiased()?0:1).putExtra("practice",practice);if(selectionId!=null)intent.putExtra("selectionId",selectionId);Motion.open(this,intent);finish();}
    private void aiSummary(){if(!AiSettings.ready(this)){ui.toast(AiSettings.notReadyMessage(this));return;}try{JSONArray weak=new JSONArray();for(int index:session.missedIndices()){JSONObject w=words.optJSONObject(index);if(w!=null)weak.put(w.optString("english"));}JSONObject payload=new JSONObject().put("total",words.length()).put("forgotten",session.repeats()).put("weakWords",weak).put("avgMastery",Mastery.average(words));ui.toast("正在生成复盘…");pendingAi=AiClient.chatJson(this,AiPrompts.systemReviewSummary(),AiPrompts.userReviewSummary(payload.toString()),new AiClient.Callback(){@Override public void onResult(JSONObject json){String body=json.optString("summary","")+"\n\n下一步："+json.optString("next","");JSONArray weakList=json.optJSONArray("weak");if(weakList!=null&&weakList.length()>0){StringBuilder w=new StringBuilder("薄弱词：");for(int i=0;i<weakList.length();i++){if(i>0)w.append("、");w.append(weakList.optString(i));}body=w+"\n\n"+body;}new AlertDialog.Builder(ReviewActivity.this).setTitle("AI 本轮复盘").setMessage(body.trim()).setPositiveButton("关闭",null).show();}@Override public void onError(String message){ui.toast(message);}});}catch(Exception e){ui.toast(e.getMessage());}}

    private void chooseSpelling(){android.content.SharedPreferences prefs=Store.prefs(this);int saved=prefs.getInt("spellingMode",SpellingPlan.NONE);boolean configured=prefs.getBoolean("spellingConfigured",false);if(configured&&!prefs.getBoolean("askSpellingMode",false)){complete(saved);return;}LinearLayout content=ui.col();content.setPadding(ui.dp(22),ui.dp(8),ui.dp(22),ui.dp(4));content.addView(ui.text("选择后会保存为默认方式。以后可在“我的 > 复习与拼写”调整。",14,WordUi.MUTED));RadioGroup choices=new RadioGroup(this);String[] labels={"拼写全部单词","拼写本词组错题本中的错词","不进行拼写"};for(int i=0;i<labels.length;i++){RadioButton option=new RadioButton(this);option.setId(i);option.setText(labels[i]);option.setMinHeight(ui.dp(48));choices.addView(option);}choices.check(Math.max(0,Math.min(2,saved)));content.addView(choices);CheckBox askAgain=new CheckBox(this);askAgain.setText("以后每轮复习后都重新询问");askAgain.setChecked(prefs.getBoolean("askSpellingMode",false));askAgain.setMinHeight(ui.dp(48));content.addView(askAgain);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(configured?"完成并选择拼写":"设置复习后的拼写").setView(content).setNegativeButton("继续练习",null).setPositiveButton("完成本轮",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int selected=choices.getCheckedRadioButtonId();if(selected<0){ui.toast("请选择一种拼写方式");return;}Store.prefs(this).edit().putInt("spellingMode",selected).putBoolean("spellingConfigured",true).putBoolean("askSpellingMode",askAgain.isChecked()).apply();dialog.dismiss();complete(selected);}));dialog.show();}
    private void complete(int spellingMode){if(completed)return;try{JSONArray all=Store.tasks(this);JSONObject task=Store.find(all,id);if(task==null||task.optBoolean("done")||task.optInt("stage")!=expectedStage){ui.toast("本轮状态已变化，未重复推进阶段");finish();return;}long now=System.currentTimeMillis();int next=expectedStage+1;JSONArray history=task.getJSONArray("history");history.put(new JSONObject().put("stage",next).put("at",now).put("repeatCount",session.repeats()).put("spellingMode",spellingMode));task.put("stage",next).put("snoozes",0);if(next>=task.getJSONArray("intervals").length())task.put("done",true);else task.put("due",Schedule.due(now,task.getJSONArray("intervals").getLong(next),Store.windows(task.optString("windows"))));if(!Store.prefs(this).edit().putString("tasks",all.toString()).putInt("spellingMode",spellingMode).commit())throw new IllegalStateException("复习结果未能写入设备");Alarms.cancel(this,id);if(!task.optBoolean("done"))Alarms.schedule(this,task);completed=true;ui.toast("本轮复习已完成");JSONArray storedWords=task.optJSONArray("words");java.util.ArrayList<Integer> wrongHits=new java.util.ArrayList<>();JSONArray wrongSource=storedWords!=null?storedWords:words;for(int i=0;i<Math.min(words.length(),wrongSource.length());i++){JSONObject word=wrongSource.optJSONObject(i);if(word!=null&&WrongBook.inBook(WrongBook.stateForWord(this,word)))wrongHits.add(i);}int[] wrongIndices=new int[wrongHits.size()];for(int i=0;i<wrongHits.size();i++)wrongIndices[i]=wrongHits.get(i);int[] indices=SpellingPlan.indices(spellingMode,words.length(),wrongIndices);int[] forgotten=session.missedIndices();if(Store.prefs(this).getBoolean("spellForgottenWords",false))indices=SpellingPlan.include(indices,forgotten,words.length());int[] examples=Store.prefs(this).getBoolean("addExamplesForForgotten",false)?ExampleActivity.missingExampleIndices(storedWords,forgotten):new int[0];if(indices.length>0){String selection=TrainingStore.forTask(this,id,indices);android.content.Intent nextStep=new android.content.Intent(this,SpellingActivity.class).putExtra("taskId",id).putExtra("selectionId",selection).putExtra("round",next).putExtra("historyAt",now).putExtra("exampleIndices",examples).putExtra("wrongMode",spellingMode==SpellingPlan.WRONG_ONLY).putExtra("sessionId",UUID.randomUUID().toString()).putExtra("attemptId",UUID.randomUUID().toString());Motion.open(this,nextStep);finish();}else if(examples.length>0){Motion.open(this,new android.content.Intent(this,ExampleActivity.class).putExtra("taskId",id).putExtra("indices",examples));finish();}else finish();}catch(Exception e){ui.toast("保存失败："+e.getMessage());}}
    @Override public void onBackPressed(){if(practice||Store.prefs(this).getBoolean("skipReviewExitPrompt",false)){finish();return;}LinearLayout body=ui.col();body.setPadding(ui.dp(20),0,ui.dp(20),0);body.addView(ui.text("单词修改已保存，但本轮不会标记完成。",14,WordUi.INK));CheckBox dontRemind=new CheckBox(this);dontRemind.setText("不再提示");dontRemind.setMinHeight(ui.dp(48));body.addView(dontRemind);new AlertDialog.Builder(this).setTitle("退出本轮复习？").setView(body).setNegativeButton("继续复习",null).setPositiveButton("退出",(d,w)->{if(dontRemind.isChecked())Store.prefs(this).edit().putBoolean("skipReviewExitPrompt",true).apply();finish();}).show();}
    @Override protected void onPause(){speech.stop();super.onPause();}
    @Override protected void onDestroy(){AiClient.cancel(pendingAi);speech.shutdown();interaction.release();super.onDestroy();}
}
